mkdir -p /tmp/wa-gate-check && cat > /tmp/wa-gate-check/check.mjs <<'EOF'
import assert from "node:assert/strict";
import { decideWhatsApp } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g5-2/bot.mjs";

const T = "1767272400"; // 2026-01-01T11:00:00Z
const at = (s) => new Date(Number(s) * 1000);
const ms = (x) => new Date(Date.parse("2026-01-01T11:00:00Z") + x);
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: T, ...over });
const r = (type, contact, now) => decideWhatsApp({ type, contact }, now);
const H = 3600e3;

// Opt-in gates everything
assert.deepEqual(r("template", c({ optedIn: false }), at(T)), { allowed: false, reason: "not_opted_in" });
assert.deepEqual(r("text", c({ optedIn: false }), at(T)), { allowed: false, reason: "not_opted_in" });
assert.deepEqual(r("text", c({ optedIn: false, lastInboundTimestamp: null }), at(T)), { allowed: false, reason: "not_opted_in" });
assert.deepEqual(r("template", { lastInboundTimestamp: null }, at(T)), { allowed: false, reason: "not_opted_in" });

// Templates: allowed any time once opted in
assert.deepEqual(r("template", c({ lastInboundTimestamp: null }), at(T)), { allowed: true, reason: null });
assert.deepEqual(r("template", c(), ms(30 * 24 * H)), { allowed: true, reason: null });

// Text: window open / boundary / closed
assert.deepEqual(r("text", c(), ms(1 * H)), { allowed: true, reason: null });
assert.deepEqual(r("text", c(), ms(24 * H - 1000)), { allowed: true, reason: null });
assert.deepEqual(r("text", c(), ms(24 * H)), { allowed: false, reason: "customer_service_window_closed" });
assert.deepEqual(r("text", c(), ms(25 * H)), { allowed: false, reason: "customer_service_window_closed" });

// Text with no inbound ever
assert.deepEqual(r("text", c({ lastInboundTimestamp: null }), at(T)), { allowed: false, reason: "no_customer_service_window" });

// Timestamp is seconds, not ms: ms form must not be read as a valid recent time
assert.deepEqual(r("text", c({ lastInboundTimestamp: T + "000" }), at(T)), { allowed: false, reason: "invalid_inbound_timestamp" });
// Numeric (non-string) timestamp is not the Meta format
assert.deepEqual(r("text", c({ lastInboundTimestamp: 1767272400 }), at(T)), { allowed: false, reason: "invalid_inbound_timestamp" });
assert.deepEqual(r("text", c({ lastInboundTimestamp: "" }), at(T)), { allowed: false, reason: "invalid_inbound_timestamp" });
assert.deepEqual(r("text", c({ lastInboundTimestamp: "abc" }), at(T)), { allowed: false, reason: "invalid_inbound_timestamp" });
// Inbound timestamp later than our clock: refuse
assert.deepEqual(r("text", c(), new Date(Date.parse("2026-01-01T10:59:59Z"))), { allowed: false, reason: "invalid_inbound_timestamp" });

// Unknown type
assert.deepEqual(r("image", c(), at(T)), { allowed: false, reason: "unsupported_message_type" });

// Bad clock input throws
assert.throws(() => decideWhatsApp({ type: "text", contact: c() }, "2026-01-01"), TypeError);

// Reasons are distinct per rule
const reasons = new Set(["not_opted_in", "customer_service_window_closed", "no_customer_service_window", "invalid_inbound_timestamp", "unsupported_message_type"]);
assert.equal(reasons.size, 5);

console.log("all checks passed");
EOF
